const mode="conquian", conquian=mode==="conquian", continental=mode==="continental-rummy", biriba=mode==="biriba";
const size=biriba||continental?11:10;
const rank=c=>c>=104?-1:c%13;
const suit=c=>Math.floor(c%52/13);
const wild=c=>c>=104||(biriba&&rank(c)===0);
function meld(cards){
 if(cards.length<3)return false;
 const natural=cards.filter(c=>!wild(c)),w=cards.length-natural.length;
 if(natural.length<2||w>(biriba?1:natural.length))return false;
 if(natural.every(c=>rank(c)===rank(natural[0])))return !conquian||new Set(natural.map(suit)).size===natural.length;
 if(!natural.every(c=>suit(c)===suit(natural[0])))return false;
 for(const lowAce of [false,true]){
  const ranks=natural.map(c=>rank(c)===12&&lowAce?-1:conquian&&rank(c)>=9?rank(c)-3:rank(c));
  if(new Set(ranks).size===ranks.length&&Math.max(...ranks)-Math.min(...ranks)<cards.length&&cards.length<=13)return true;
 }
 return false;
}
function groups(hand){
 const out=[];
 for(let a=0;a<hand.length;a++)for(let b=a+1;b<hand.length;b++)for(let c=b+1;c<hand.length;c++){
  const group=[hand[a],hand[b],hand[c]];
  if(meld(group))out.push(group);
 }
 return out;
}
function layout(hand){
 if(!hand.length)return [];
 for(let mask=1;mask<2**hand.length;mask+=2){
  const group=hand.filter((_,i)=>mask&(1<<i));
  if(!meld(group))continue;
  const rest=layout(hand.filter((_,i)=>!(mask&(1<<i))));
  if(rest)return [group,...rest];
 }
 return null;
}
function finish(s,ctx,winner){
 s.winners=winner>=0?[winner]:[];
 const humans=ctx.players.filter(p=>p.kind==="human"&&p.active!==false);
 const paid=winner>=0&&humans.includes(ctx.players[winner])?[ctx.players[winner]]:humans;
 return {state:s,turn:null,payouts:Object.fromEntries(paid.map((p,i)=>[p.id,Math.floor(ctx.pot/paid.length)+Number(i<ctx.pot%paid.length)]))};
}
function moves(s){
 const hand=s.hands[s.seat], pile=s.pile, top=pile[pile.length-1];
 if(s.phase===0){
  if(conquian){
   const options=groups([...hand,top]).filter(g=>g.includes(top)).map(cards=>({cards}));
   s.melds[s.seat].forEach((g,i)=>{if(meld([...g,top]))options.push({extend:i});});
   return [...options,{pass:true}];
  }
  return [{draw:0},...(pile.length?[{draw:1}]:[])];
 }
 if(!continental&&!biriba&&!conquian){
  const close=hand.find(c=>layout(hand.filter(x=>x!==c)));
  return [...(close===undefined?[]:[{close}]),...hand.map(discard=>({discard}))];
 }
 const options=hand.map(discard=>({discard}));
 if(continental&&!s.melds[s.seat].length){
  const sets=groups(hand).filter(g=>g.filter(c=>!wild(c)).every(c=>rank(c)===rank(g.find(c=>!wild(c)))));
  for(const a of sets)for(const b of sets)if(a[0]<b[0]&&a.every(c=>!b.includes(c)))options.unshift({cards:[...a,...b]});
 }else if(!conquian){
  for(const cards of groups(hand))options.unshift({cards});
  s.melds[s.seat].forEach((g,i)=>hand.forEach(c=>{if(meld([...g,c]))options.unshift({append:[i,c]});}));
 }
 return options;
}
const game={
 newMatch(ctx){
  let seed=2166136261;
  for(const p of ctx.players)for(const c of p.id)seed=Math.imul(seed^c.charCodeAt(0),16777619);
  const deck=Array.from({length:conquian?52:108},(_,i)=>i).filter(c=>!conquian||![6,7,8].includes(rank(c)));
  for(let i=deck.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[deck[i],deck[j]]=[deck[j],deck[i]];}
  const hands=ctx.players.map((_,i)=>deck.slice(i*size,i*size+size)),stock=deck.slice(hands.length*size);
  const reserve=biriba?hands.map(()=>stock.splice(0,11)):hands.map(()=>[]);
  return {state:{hands,stock,reserve,pile:[stock.shift()],melds:hands.map(()=>[]),seat:0,phase:0,turns:0,winners:[]},turn:[ctx.players[0].id]};
 },
 applyMove(s,id,m,ctx){
  const fail=()=>{throw new InvalidMove("Choose a legal move on your turn.");};
  if(!m||Object.keys(m).length!==1||s.winners.length||ctx.players[s.seat].id!==id)fail();
  const i=s.seat;
  const options=moves(s);
  if(!options.some(o=>JSON.stringify(o)===JSON.stringify(m)))fail();
  const state={...s,hands:s.hands.map(h=>[...h]),stock:[...s.stock],pile:[...s.pile],reserve:s.reserve.map(h=>[...h]),melds:s.melds.map(gs=>gs.map(g=>[...g])),turns:s.turns+1};
  let hand=state.hands[i];
  if(m.pass){
   if(!state.stock.length)return finish(state,ctx,-1);
   state.pile=[state.stock.shift()];state.seat=1-i;
  }else if(m.draw!==undefined){
   if(m.draw===0&&!state.stock.length)return finish(state,ctx,-1);
   if(m.draw&&biriba)hand.push(...state.pile.splice(0));
   else hand.push(m.draw?state.pile.pop():state.stock.shift());
   state.phase=1;
  }else if(m.close!==undefined)return finish(state,ctx,i);
  else if(m.discard!==undefined){
   hand.splice(hand.indexOf(m.discard),1);state.pile.push(m.discard);
   state.phase=0;state.seat=(i+1)%state.hands.length;
  }else{
   if(conquian){
    const up=state.pile.pop();
    if(m.extend!==undefined)state.melds[i][m.extend].push(up);
    else {state.melds[i].push(m.cards);hand=state.hands[i]=hand.filter(c=>!m.cards.includes(c));}
    state.phase=1;
   }else if(m.append){
    const [group,c]=m.append;state.melds[i][group].push(c);hand.splice(hand.indexOf(c),1);
   }else{
    state.melds[i].push(...(m.cards.length===6?[m.cards.slice(0,3),m.cards.slice(3)]:[m.cards]));
    hand=state.hands[i]=hand.filter(c=>!m.cards.includes(c));
   }
  }
  if(conquian&&state.melds[i].flat().length>=11)return finish(state,ctx,i);
  if(!hand.length&&!conquian){
   if(state.reserve[i].length){state.hands[i]=state.reserve[i];state.reserve[i]=[];}
   else if(!biriba||state.melds[i].some(g=>g.length>=7))return finish(state,ctx,i);
   else return finish(state,ctx,-1);
  }
  if(state.turns>=100)return finish(state,ctx,-1);
  return {state,turn:[ctx.players[state.seat].id]};
 },
 viewFor(s,id,ctx){
  const {hands,stock,reserve,pile,...visible}=s,i=ctx.players.findIndex(p=>p.id===id);
  return {...visible,hand:hands[i]??[],counts:hands.map(h=>h.length),top:pile[pile.length-1]??-1,choices:i===s.seat?moves(s):[]};
 },
 computerMove(s){
  const options=moves(s);
  if(conquian)return options[0];
  if(s.phase===0)return {draw:0};
  return options.find(m=>m.cards||m.append||m.close!==undefined)??options[options.length-1];
 },
 randomMove(s){return this.computerMove(s);}
};

